def _source_test_candidate(
    *,
    target: str,
    level_range: tuple[int, int],
    score: float = 100,
    mobile_vnum: int = 100,
    room_vnum: int = 200,
    status: str = "caution",
    boot_kills: int = 0,
    autonomy_rejections: tuple[str, ...] = (),
    specials: tuple[str, ...] = (),
    hazards: tuple[str, ...] = (),
) -> HuntCandidate:
    return HuntCandidate(
        status=status,
        score=score,
        area_file="test.are",
        mobile_vnum=mobile_vnum,
        target=target,
        target_keyword=target.split()[-1],
        level=level_range[1] - 2,
        room_vnum=room_vnum,
        room_name="a test room",
        route=("south",),
        source_spawn_limit=1,
        room_spawn_count=1,
        boot_kills=boot_kills,
        loot=("a saleable sword",),
        source_value=10,
        contained_coins=0,
        hazards=hazards,
        estimated_level_range=level_range,
        estimated_base_hp_range=(10, 20),
        estimated_peak_round_damage=10,
        autonomy_rejections=autonomy_rejections,
        specials=specials,
    )


def test_source_ranked_frontier_diagnosis_records_reboot_scoped_blockers() -> None:
    safe = _source_test_candidate(
        target="a safe target",
        level_range=(24, 26),
        mobile_vnum=101,
        room_vnum=201,
    )
    sanctuary = replace(
        _source_test_candidate(
            target="a sanctuary target",
            level_range=(25, 26),
            mobile_vnum=102,
            room_vnum=202,
        ),
        estimated_base_hp_range=(10, 200),
    )
    state: dict[str, object] = {
        "level": 25,
        "max_hp": 100,
        "move": 100,
        "max_move": 100,
        "affects": [],
        "world_boot_id": "boot-1",
        "campaign_below_band_policy_exclusions": {
            "source-ranked-hunt-test-101-201-25": {
                "boot_id": "boot-1",
                "level": 25,
                "targets": ["safe target"],
            }
        },
    }

    _record_source_ranked_frontier_diagnosis(
        state,
        (safe, sanctuary),
        (),
        character_level=25,
        character_max_hp=100,
        source_world=None,
    )

    diagnosis = state[_SOURCE_RANKED_FRONTIER_DIAGNOSIS_KEY]
    assert diagnosis["candidate_count"] == 2
    assert diagnosis["autonomous_safe_count"] == 2
    assert diagnosis["same_boot_below_band_count"] == 1
    assert diagnosis["sanctuary_required_count"] == 1
    assert diagnosis["no_sanctuary_count"] == 0
    assert {item["reason"] for item in diagnosis["top_blockers"]} >= {
        "same-boot below-band evidence",
        "sanctuary reserve required",
    }


