        {
            "level": 21,
            "world_boot_id": "boot-1",
            "campaign_primary_weapon": "a dagger",
            "campaign_fastwalk_source_consider_outcomes": {"stale": True},
            "campaign_fastwalk_source_below_band_sightings": [
                {"source_policy_id": "stale", "target": "stale"}
            ],
        },
