def test_source_ranked_fame_window_requires_six_levels_for_ordinary_targets() -> None:
    exactly_five = _source_test_candidate(
        target="the five-level target",
        level_range=(29, 29),
    )
    six_levels = _source_test_candidate(
        target="the six-level target",
        level_range=(30, 30),
    )
    famous_lower = _source_test_candidate(
        target="the famous target",
        level_range=(20, 20),
    )

    assert (
        _source_ranked_fame_level_window(
            exactly_five,
            character_level=24,
            awards_fame=False,
        )
        is None
    )
    assert _source_ranked_fame_level_window(
        six_levels,
        character_level=24,
        awards_fame=False,
    ) == (30, 30)
    assert _source_ranked_fame_level_window(
        famous_lower,
        character_level=24,
        awards_fame=True,
    ) == (20, 20)


def test_fame_window_matches_current_dd4_fight_source() -> None:
    fight_source = (
        current_source_directory().parent / "src" / "fight.c"
    ).read_text(encoding="utf-8", errors="replace")
    fame_condition = re.search(
        r"ACT_IS_FAMOUS.*?level_dif\s*>\s*-10.*?\|\|\s*level_dif\s*>\s*5",
        fight_source,
        flags=re.DOTALL,
    )

    assert fame_condition is not None


def test_fame_window_matches_current_dd4_help_entry() -> None:
    help_source = (current_source_directory() / "helpfile.are").read_text(
        encoding="utf-8",
        errors="replace",
    )

    assert re.search(
        r"0 FAME~.*?Killing mobs 6 or levels higher",
        help_source,
        flags=re.DOTALL,
    ) is not None


def test_source_ranked_famous_gas_probe_requires_healer_and_sanctuary() -> None:
    world = load_world_source(
        Path("runs/dd4-source/server/area"),
        include_all_areas=True,
    )
    skills = [
        "armed combat knowledge",
        "backstab",
        "defense knowledge",
        "disarm",
        "dodge",
        "heighten senses",
        "hide",
        "knife toss",
        "parry",
        "second attack",
        "sneak",
        "stealth techniques",
        "thievery skills",
        "third attack",
        "unarmed combat knowledge",
    ]
    skill_levels = {
        "armed combat knowledge": 67,
        "backstab": 69,
        "defense knowledge": 61,
        "disarm": 51,
        "dodge": 50,
        "heighten senses": 99,
        "hide": 23,
        "knife toss": 48,
        "parry": 43,
        "second attack": 77,
        "sneak": 99,
        "stealth techniques": 60,
        "thievery skills": 46,
        "third attack": 61,
        "unarmed combat knowledge": 46,
    }
    [candidate] = [
        item
        for item in rank_hunt_candidates(
            world,
            character_level=24,
            character_class="thief",
            character_subclass="ninja",
            known_skills=skills,
            known_skill_levels=skill_levels,
            include_xp_only=True,
            include_below_band=False,
            character_max_hp=334,
            include_level_ceiling_candidates=True,
            level_ceiling_offset=9,
            include_all_areas=True,
            character_alignment=1000,
        )
        if item.mobile_vnum == 6112
    ]
    state = {
        "level": 24,
        "max_hp": 334,
        "max_move": 380,
        "world_boot_id": "boot-1",
        "campaign_last_policy": "world-time-probe",
        "character_class": "thief",
        "subclass": "ninja",
        "campaign_known_skills": skills,
        "campaign_known_skill_levels": skill_levels,
        "equipment": [
            {
                "name": "a long slim dagger",
                "slot": "wield",
                "vnum": 5252,
                "wear_loc": 16,
            }
        ],
        "stats": {"damroll": 5, "dex_mod": 27, "swift": 9},
        "verified_combat_pouch_potions": {"purple": 1},
        "room_vnum": "3054",
        "affects": [],
    }

    assert world.mobiles[6112].awards_fame is True
    assert candidate.specials == ("spec_breath_gas",)
    assert _source_ranked_fame_recovery_candidate_allowed(
        candidate,
        world,
        state,
        character_level=24,
        character_max_hp=334,
    ) is True
    assert _source_ranked_protected_special_hp_fuzz_probe_allowed(
        candidate,
        state,
        character_level=24,
        source_world=world,
    ) is True
    target_stops = [
        stop
        for stop in _source_ranked_hunt_stops(
            candidate,
            world,
            character_level=24,
            state=state,
            fame_recovery=True,
        )
        if stop.target is not None
    ]
    assert len(target_stops) == 1
    assert target_stops[0].allow_protected_special_hp_fuzz_probe is True
    assert _select_source_ranked_fame_recovery_candidate(
        (candidate,),
        world,
        state,
        character_level=24,
        character_max_hp=334,
    ) == candidate
    (stop,) = _source_ranked_hunt_stops(
        candidate,
        world,
        character_level=24,
        state=state,
        fame_recovery=True,
    )
    assert stop.source_mobile_vnum == 6112
    assert stop.require_sanctuary is True
    assert stop.allow_protected_special_hp_fuzz_probe is True
    assert stop.allow_healer_poison_recovery is True
    assert stop.source_target_hp_ceiling == 945
    assert stop.source_peak_round_damage == 276
    assert stop.protected_source_peak_round_damage == 138

    no_healer = {**state, "room_vnum": "3001"}
    assert _source_ranked_fame_recovery_candidate_allowed(
        candidate,
        world,
        no_healer,
        character_level=24,
        character_max_hp=334,
    ) is False
    no_sanctuary = {**state, "verified_combat_pouch_potions": {}}
    assert _source_ranked_fame_recovery_candidate_allowed(
        candidate,
        world,
        no_sanctuary,
        character_level=24,
        character_max_hp=334,
    ) is False


