    protected_state = {
        **state,
        "combat_pouch_potions": {"purple": 1},
    }
    assert _source_ranked_unprotected_hp_fuzz_probe_allowed(
        candidate,
        protected_state,
        character_level=25,
    ) is False
    assert _source_ranked_candidate_requires_sanctuary_for_state(
        candidate,
        protected_state,
        character_level=25,
    ) is True


