def test_source_ranked_wanderer_routes_below_band_aggressive_locations() -> None:
    world = load_world_source(
        Path("runs/dd4-source/server/area"),
        include_all_areas=True,
    )
    candidate = _source_mobile_candidate(
        world,
        mobile_vnum=1112,
        origin_room_vnum=1111,
        target_keyword="thain",
        target="the Thain",
    )

    (locator, *search_stops) = _source_ranked_hunt_stops(candidate, world)
    routes = dict(locator.where_location_routes)

    assert search_stops
    assert routes["pig pen"]
    assert routes["a chicken coop"]
    assert "pig pen" not in locator.abort_if_where_room_names
    assert "a chicken coop" not in locator.abort_if_where_room_names
    assert locator.abort_if_where_location_unknown is True


def test_source_ranked_reset_retry_reopens_absence_but_not_route_hazard() -> None:
    absent_candidate = _source_test_candidate(
        target="a white dwarf",
        level_range=(15, 19),
    )
    absent_policy_id = _source_ranked_policy_id(
        absent_candidate,
        character_level=19,
    )
    absent_state = {
        "world_boot_id": "boot-1",
        "campaign_research_results": {
            absent_policy_id: {
                "boot_id": "boot-1",
                "observed": False,
                "absent": True,
                "viable": False,
            }
        },
        "campaign_research_absence_cooldowns": {absent_policy_id: 3},
    }

    assert (
        _source_ranked_result_status(
            absent_candidate,
            absent_state,
            character_level=19,
        )
        == "cooldown"
    )
    assert (
        _source_ranked_result_status(
            absent_candidate,
            absent_state,
            character_level=19,
            allow_cooldown_retry=True,
        )
        == "retryable"
    )

    hazard_state = {
        "world_boot_id": "boot-1",
        "campaign_research_results": {
            absent_policy_id: {
                "boot_id": "boot-1",
                "observed": False,
                "route_hazard": "source hazard",
                "viable": False,
            }
        },
        "campaign_research_absence_cooldowns": {absent_policy_id: 3},
    }
    assert (
        _source_ranked_result_status(
            absent_candidate,
            hazard_state,
            character_level=19,
            allow_cooldown_retry=True,
        )
        == "cooldown"
    )


def test_retry_stalled_reopens_only_an_allowed_route_program_preflight() -> None:
    candidate = replace(
        _source_test_candidate(
            target="a plain route-program target",
            level_range=(20, 24),
            mobile_vnum=20015,
            room_vnum=20015,
        ),
        route_attack_program_mobile_vnums=(3064,),
        route_preflight_room_vnum="3001",
        route_preflight_command="where drunk",
        route_preflight_target="the drunk",
        route_preflight_level_range=(1, 4),
        route_preflight_hard_hazard=True,
        route_preflight_route_room_names=("temple square", "the target"),
    )
    policy_id = _source_ranked_policy_id(candidate, character_level=24)
    state = {
        "level": 24,
        "max_hp": 342,
        "world_boot_id": "boot-1",
        "campaign_research_results": {
            policy_id: {
                "boot_id": "boot-1",
                "observed": False,
                "viable": False,
                "route_hazard": (
                    "field route preflight found source-registered hazard "
                    "'the drunk' in room 3001"
                ),
            }
        },
        "campaign_research_absence_cooldowns": {policy_id: 3},
    }
    world = WorldSource(
        mobiles={
            3064: MobileSource(
                3064,
                "drunk",
                "the drunk",
                2,
                0,
                0,
                "midgaard.are",
                programs=(
                    MobileProgram(
                        "greet_prog",
                        "10",
                        ("mpkill $n",),
                    ),
                ),
            ),
        }
    )

    assert (
        _select_source_ranked_hunt_candidate(
            (candidate,),
            state,
            world=world,
            character_level=24,
            character_max_hp=342,
        )
        is None
    )
    selected = _select_source_ranked_hunt_candidate(
        (candidate,),
        state,
        world=world,
        character_level=24,
        character_max_hp=342,
        allow_route_program_retry=True,
    )
    assert selected == candidate


