def test_policy_refresh_preserves_hard_shadow_guardian_preflight() -> None:
    policy_id = "galaxy-white-dwarf-probe-17-20"
    source_ranked_id = "source-ranked-hunt-galaxy-9306-9306-19"
    shadow_hazard = (
        "field route preflight found source-registered hazard "
        "'shadow guardian' in room 1300"
    )
    refreshed = _refresh_policy_revision(
        {
            "campaign_policy_revision": 111,
            "level": 19,
            "campaign_last_policy": policy_id,
            "campaign_fastwalk_abort_reason": shadow_hazard,
            "campaign_research_results": {
                policy_id: {
                    "observed": False,
                    "viable": False,
                    "route_hazard": shadow_hazard,
                    "boot_id": "boot-1",
                },
                source_ranked_id: {
                    "observed": False,
                    "viable": False,
                    "route_hazard": shadow_hazard,
                    "boot_id": "boot-1",
                },
                "unknown-route": {
                    "observed": False,
                    "viable": False,
                    "route_hazard": (
                        "field route preflight found source-registered hazard "
                        "'ancient void sentinel' in room 1300"
                    ),
                    "boot_id": "boot-1",
                },
            },
            "campaign_research_absence_cooldowns": {
                policy_id: 3,
                source_ranked_id: 3,
                "unknown-route": 3,
            },
        }
    )

    assert refreshed["campaign_research_results"][policy_id][
        "route_hazard"
    ] == shadow_hazard
    assert refreshed["campaign_research_results"][source_ranked_id][
        "route_hazard"
    ] == shadow_hazard
    assert refreshed["campaign_research_results"]["unknown-route"]
    assert refreshed["campaign_research_absence_cooldowns"] == {
        policy_id: 3,
        source_ranked_id: 3,
        "unknown-route": 3,
    }
    assert refreshed["campaign_fastwalk_abort_reason"] == shadow_hazard


