def test_source_ranked_xp_loss_route_reopens_with_sanctuary_reserve() -> None:
    failed = _source_test_candidate(
        target="a recovered sentinel",
        level_range=(17, 19),
        mobile_vnum=20004,
        room_vnum=20004,
    )
    failed_policy_id = _source_ranked_policy_id(
        failed,
        character_level=18,
    )
