def test_source_ranked_selection_can_reuse_meaningful_productive_stop() -> None:
    candidate = _source_test_candidate(
        target="a productive sentinel",
        level_range=(13, 17),
        boot_kills=3,
    )
    policy_id = _source_ranked_policy_id(candidate, character_level=19)
    state = {
        "level": 19,
        "world_boot_id": "boot-1",
        "campaign_research_results": {
            policy_id: {
                "boot_id": "boot-1",
                "observed": True,
                "viable": True,
                "completed_kill": True,
            }
        },
    }

    assert (
        _select_source_ranked_hunt_candidate(
            (candidate,),
            state,
            character_level=19,
        )
        is None
    )
    assert (
        _select_source_ranked_hunt_candidate(
            (candidate,),
            state,
            character_level=19,
            allow_repeated_policy_ids={policy_id},
        )
        == candidate
    )

    exhausted_state = {
        **state,
        "campaign_last_policy": policy_id,
        _SOURCE_RANKED_RETRY_EXHAUSTED_KEY: policy_id,
        _SOURCE_RANKED_RETRY_EXHAUSTED_BOOT_KEY: "boot-1",
    }

    assert (
        _select_source_ranked_hunt_candidate(
            (candidate,),
            exhausted_state,
            character_level=19,
            allow_repeated_policy_ids={policy_id},
        )
        is None
    )

    rotated_state = {
        **exhausted_state,
        "campaign_last_policy": "fame-recovery-test",
    }
    assert (
        _select_source_ranked_hunt_candidate(
            (candidate,),
            rotated_state,
            character_level=19,
            allow_repeated_policy_ids={policy_id},
        )
        is None
    )
    assert (
        _select_source_ranked_hunt_candidate(
            (candidate,),
            rotated_state,
            character_level=19,
            allow_retry_exhausted_repeat=True,
            allow_repeated_policy_ids={policy_id},
        )
        == candidate
    )


