def test_source_ranked_mage_familiar_probe_opens_outdoor_plain_target() -> None:
    world = load_world_source(
        Path("runs/dd4-source/server/area"),
        include_all_areas=True,
    )
    world = replace(
        world,
        mobiles={
            vnum: replace(
                mobile,
                programs=(),
                act_flags=(
                    mobile.act_flags & ~ACT_AGGRESSIVE
                    if vnum == 6313
                    else mobile.act_flags
                ),
            )
            for vnum, mobile in world.mobiles.items()
        },
    )
    candidates = rank_hunt_candidates(
        world,
        character_level=18,
        character_class="Mage",
        known_skills=("burning hands", "summon familiar"),
        known_skill_levels={"burning hands": 31, "summon familiar": 42},
        include_xp_only=True,
        include_level_ceiling_candidates=True,
        level_ceiling_offset=1,
        include_all_areas=True,
        character_max_hp=218,
        recall_origins={0: 3001},
    )
    guardian = next(
        candidate
        for candidate in candidates
        if candidate.mobile_vnum == 6313 and candidate.room_vnum == 6367
    )
    state = {
        "level": 18,
        "max_hp": 218,
        "max_mana": 628,
        "character_class": "Mage",
        "world_boot_id": "boot-1",
        "campaign_known_skills": ["burning hands", "summon familiar"],
        "campaign_known_skill_levels": {
            "burning hands": 31,
            "summon familiar": 42,
        },
    }

    assert _source_ranked_familiar_probe_allowed(
        guardian,
        state,
        character_level=18,
        source_world=world,
    ) is True
    assert _select_source_ranked_hunt_candidate(
        (guardian,),
        state,
        world=world,
        character_level=18,
        character_max_hp=218,
    ) == guardian
    assert _source_ranked_candidate_requires_sanctuary_for_state(
        guardian,
        state,
        character_level=18,
        source_world=world,
    ) is False
    target_stops = tuple(
        stop
        for stop in _source_ranked_hunt_stops(
            guardian,
            world,
            character_level=18,
            state=state,
        )
        if stop.source_mobile_vnum == guardian.mobile_vnum
    )
    assert target_stops
    assert all(stop.require_familiar for stop in target_stops)
    assert all(stop.require_damage_window_probe for stop in target_stops)

    policy_id = _source_ranked_policy_id(guardian, character_level=18)
    revalidation_state = {
        **state,
        _PROTECTION_RECOVERY_KEY: {
            "boot_id": "boot-1",
            "level": 18,
            "policy_id": policy_id,
            "trigger": "hard_health_floor",
            "xp_delta": 26,
        },
    }
    _arm_source_ranked_familiar_revalidation(
        revalidation_state,
        (guardian,),
        character_level=18,
        source_world=world,
    )
    assert _source_ranked_familiar_revalidation_pending(
        revalidation_state,
        policy_id=policy_id,
    ) is True
    assert _select_source_ranked_hunt_candidate(
        (guardian,),
        revalidation_state,
        world=world,
        character_level=18,
        character_max_hp=218,
    ) == guardian
    _mark_source_ranked_familiar_revalidation(
        revalidation_state,
        guardian,
        character_level=18,
    )
    assert _source_ranked_familiar_revalidation_attempted(
        revalidation_state,
        policy_id=policy_id,
    ) is True
    assert _source_ranked_candidate_blocked_by_protection_recovery(
        guardian,
        revalidation_state,
        character_level=18,
        source_world=world,
    ) is True
    succeeded = {
        **revalidation_state,
        _SOURCE_RANKED_FAMILIAR_REVALIDATION_KEY: {
            **revalidation_state[_SOURCE_RANKED_FAMILIAR_REVALIDATION_KEY],
            "status": "succeeded",
        },
    }
    succeeded.pop(_PROTECTION_RECOVERY_KEY, None)
    assert _source_ranked_familiar_revalidation_attempted(
        succeeded,
        policy_id=policy_id,
    ) is True
    assert _source_ranked_candidate_blocked_by_protection_recovery(
        guardian,
        succeeded,
        character_level=18,
        source_world=world,
    ) is True
    closed = _campaign_segment_end_state(
        revalidation_state,
        {"world_boot_id": "boot-1"},
        execution="source-ranked-hunt",
        policy_id=policy_id,
    )
    assert closed[_SOURCE_RANKED_FAMILIAR_REVALIDATION_KEY]["status"] == "closed"


