def test_funding_candidate_prefers_completed_target_for_flight_money(
    tmp_path,
    monkeypatch,
) -> None:
    def candidate(target: str, value: int) -> HuntCandidate:
        return HuntCandidate(
            status="promising",
            score=value,
            area_file="test.are",
            mobile_vnum=value,
            target=target,
            target_keyword=target.split()[-1],
            level=15,
            room_vnum=value,
            room_name="a test room",
            route=("south",),
            source_spawn_limit=1,
            room_spawn_count=1,
            boot_kills=0,
            loot=("a saleable sword",),
            source_value=value,
            contained_coins=0,
            hazards=(),
            estimated_level_range=(13, 17),
            estimated_base_hp_range=(10, 20),
            estimated_peak_round_damage=10,
            autonomy_rejections=(),
        )

    completed = candidate("completed carrier", 20)
    completed = replace(completed, boot_kills=3)
    fresh = candidate("fresh carrier", 30)
    monkeypatch.setattr(
        "dd4tester.campaign.load_world_source",
        lambda *args, **kwargs: object(),
    )
    monkeypatch.setattr(
        "dd4tester.campaign.rank_hunt_candidates",
        lambda *args, **kwargs: [completed, fresh],
    )
    state = {
        "level": 18,
        _PROVISION_FUNDING_ATTEMPTS_KEY: [
            {
                "boot_id": "boot-1",
                "candidate_key": "test.are:20:20",
                "completed_kill": True,
            }
        ],
    }

    ordinary = _select_provision_funding_candidate(
        state,
        character_level=18,
        boot_kill_counts={},
        boot_id="boot-1",
        source_directory=tmp_path,
        gear_catalog=None,
    )
    flight = _select_provision_funding_candidate(
        state,
        character_level=18,
        boot_kill_counts={},
        boot_id="boot-1",
        source_directory=tmp_path,
        gear_catalog=None,
        prefer_completed_funding_candidate=True,
    )

    assert ordinary is fresh
    assert flight is completed

    below_band_state = {
        **state,
        "campaign_below_band_policy_exclusions": {
            "provision-funding": {
                "level": 18,
                "boot_id": "boot-1",
                "targets": ["completed carrier"],
            }
        },
    }
    flight_after_below_band_completion = _select_provision_funding_candidate(
        below_band_state,
        character_level=18,
        boot_kill_counts={},
        boot_id="boot-1",
        source_directory=tmp_path,
        gear_catalog=None,
        prefer_completed_funding_candidate=True,
    )

    assert flight_after_below_band_completion is fresh

    state_after_failed_retry = {
        **state,
        _PROVISION_FUNDING_ATTEMPTS_KEY: [
            *state[_PROVISION_FUNDING_ATTEMPTS_KEY],
            {
                "boot_id": "boot-1",
                "candidate_key": "test.are:20:20",
                "completed_kill": False,
            },
        ],
        _PROVISION_FUNDING_LAST_ATTEMPT_KEY: {
            "boot_id": "boot-1",
            "candidate_key": "test.are:20:20",
            "completed_kill": False,
        },
    }
    rotated_after_failed_retry = _select_provision_funding_candidate(
        state_after_failed_retry,
        character_level=18,
        boot_kill_counts={},
        boot_id="boot-1",
        source_directory=tmp_path,
        gear_catalog=None,
        prefer_completed_funding_candidate=True,
    )

    assert rotated_after_failed_retry is fresh


