def test_source_food_reserve_dispatch_collects_without_shop_resupply(
    tmp_path,
    monkeypatch,
) -> None:
    config_path, database = _write_campaign_files(tmp_path)
    spec = load_campaign_spec(config_path)
    candidate = replace(
        _source_test_candidate(
            target="food stash",
            level_range=(0, 0),
            mobile_vnum=0,
            room_vnum=331,
        ),
        area_file="plains_north.are",
        target_keyword="wabbit",
        route=("south", "west"),
        loot=("a rabbit roast",),
        source_value=24,
        ground_loot_keywords=("wabbit",),
        ground_loot_object_vnums=(309,),
        is_food_stash=True,
        estimated_move_cost=42,
    )
    world = WorldSource()
    captured: dict[str, object] = {}

    class FakeRunner:
        def __init__(self, character, profile_path, **kwargs):
            captured.update(kwargs)

        async def run(self):
            return _record_segment_run(
                database,
                spec.character_profile,
                {"level": 24},
            )

    monkeypatch.setattr("dd4tester.campaign.StarterBotRunner", FakeRunner)
    monkeypatch.setattr(
        "dd4tester.campaign.load_world_source",
        lambda *args, **kwargs: world,
    )
    policy = replace(
        _SOURCE_RANKED_FOOD_RESERVE_POLICY,
        policy_id=_source_food_policy_id(candidate, character_level=24),
        minimum_level=24,
        maximum_level=24,
    )

    asyncio.run(
        _run_policy_segment(
            spec.character,
            spec.character_profile,
            policy,
            current_state={
                "level": 24,
                "move": 380,
                "max_move": 380,
                "hunger": -10,
            },
            character_level=24,
            source_food_candidate=candidate,
        )
    )

    [stop] = captured["fastwalk_hunt_stops"]
    assert stop.target is None
    assert stop.required_items == ("a rabbit roast",)
    assert stop.allow_below_band_for_required_loot is True
    assert stop.source_loot_object_vnums == (309,)
    assert stop.minimum_health_ratio == 0.0
    assert captured["fastwalk_origin_actions"] == ("drink skin",)
    assert captured["fastwalk_kill_limit"] is None
    assert captured["fastwalk_defer_provision_resupply"] is True
    assert captured["urgent_food_acquisition"] is True
    assert captured["require_fastwalk_kill"] is False
    assert captured["fastwalk_required_move"] == 57

    captured.clear()
    asyncio.run(
        _run_policy_segment(
            spec.character,
            spec.character_profile,
            policy,
            current_state={
                "level": 24,
                "move": 380,
                "max_move": 380,
                "hunger": 14,
            },
            character_level=24,
            source_food_candidate=candidate,
        )
    )

    assert captured["urgent_food_acquisition"] is False


@pytest.mark.parametrize(
    ("initial_inventory", "initial_hunger", "expected_stop_count"),
    [
        ([], -3, 2),
        ([[{"short_desc": "a big pot pie"}]], 5, 2),
    ],
)
def test_source_food_reserve_chains_a_distinct_same_area_reset(
    tmp_path,
    monkeypatch,
    initial_inventory,
    initial_hunger,
    expected_stop_count,
) -> None:
    config_path, database = _write_campaign_files(tmp_path)
    spec = load_campaign_spec(config_path)
    primary = replace(
        _source_test_candidate(
            target="food stash",
            level_range=(0, 0),
            mobile_vnum=0,
            room_vnum=6016,
            status="promising",
        ),
        area_file="haon.are",
        target_keyword="mushroom",
        route=("south",),
        loot=("a mushroom",),
        source_value=6,
        ground_loot_keywords=("mushroom",),
        ground_loot_object_vnums=(6011,),
        is_food_stash=True,
        estimated_move_cost=42,
    )
    companion = replace(
        primary,
        target_keyword="toadstool",
        room_vnum=6111,
        loot=("a toadstool",),
        source_value=12,
        ground_loot_keywords=("toadstool",),
        ground_loot_object_vnums=(6106,),
    )
    world = WorldSource()
    captured: dict[str, object] = {}

    class FakeRunner:
        def __init__(self, character, profile_path, **kwargs):
            captured.update(kwargs)

        async def run(self):
            return _record_segment_run(
                database,
                spec.character_profile,
                {"level": 24},
            )

    monkeypatch.setattr("dd4tester.campaign.StarterBotRunner", FakeRunner)
    monkeypatch.setattr(
        "dd4tester.campaign.load_world_source",
        lambda *args, **kwargs: world,
    )
    monkeypatch.setattr(
        "dd4tester.campaign.rank_food_stashes",
        lambda *args, **kwargs: [primary, companion],
    )
    monkeypatch.setattr(
        "dd4tester.campaign._source_ranked_route_has_static_safe_live_navigation_path",
        lambda *args, **kwargs: True,
    )
    monkeypatch.setattr(
        "dd4tester.campaign._source_ranked_inter_candidate_route",
        lambda *args, **kwargs: ("6100", "6111"),
    )
    monkeypatch.setattr(
        "dd4tester.campaign._source_ranked_inter_route_live_navigation",
        lambda *args, **kwargs: {},
    )
    policy = replace(
        _SOURCE_RANKED_FOOD_RESERVE_POLICY,
        policy_id=_source_food_policy_id(primary, character_level=24),
        minimum_level=24,
        maximum_level=24,
    )

    asyncio.run(
        _run_policy_segment(
            spec.character,
            spec.character_profile,
            policy,
            current_state={
                "level": 24,
                "move": 380,
                "max_move": 380,
                "hunger": initial_hunger,
                "inventory": initial_inventory,
                "affects": [],
                "world_boot_id": "boot-1",
            },
            character_level=24,
            source_food_candidate=primary,
        )
    )

    stops = tuple(captured["fastwalk_hunt_stops"])
    assert len(stops) == expected_stop_count
    assert [stop.required_items for stop in stops] == [
        ("a mushroom",),
        ("a toadstool",),
    ]
    assert stops[0].route_vnums == ()
    assert stops[1].route_vnums == ("6100", "6111")
    assert stops[1].source_policy_id == _source_food_policy_id(
        companion,
        character_level=24,
    )
    assert captured["fastwalk_required_move"] == 59


def test_source_food_selector_allows_only_bounded_below_band_transit(
    tmp_path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    transit_candidate = replace(
        _source_test_candidate(
            target="food stash",
            level_range=(0, 0),
            mobile_vnum=0,
            room_vnum=5217,
            status="reject",
            autonomy_rejections=tuple(_SOURCE_FOOD_TRANSIT_REJECTIONS),
        ),
        area_file="thalos.are",
        target_keyword="chunk",
        loot=("a chunk of meat",),
        source_value=24,
        ground_loot_keywords=("chunk",),
        ground_loot_object_vnums=(5219,),
        is_food_stash=True,
        estimated_move_cost=107,
    )
    unsafe_candidate = replace(
        transit_candidate,
        room_vnum=331,
        autonomy_rejections=(
            *_SOURCE_FOOD_TRANSIT_REJECTIONS,
            "a higher-level aggressive wanderer can reach the route",
        ),
    )
    monkeypatch.setattr(
        "dd4tester.campaign.load_world_source",
        lambda *args, **kwargs: WorldSource(),
    )
    monkeypatch.setattr(
        "dd4tester.campaign.rank_food_stashes",
        lambda *args, **kwargs: [unsafe_candidate, transit_candidate],
    )
    source_directory = tmp_path / "area"
    source_directory.mkdir()

    selected = _select_source_food_candidate(
        {
            "level": 24,
            "hunger": -10,
            "world_boot_id": "boot-1",
            "max_move": 380,
            "affects": [],
        },
        source_directory=source_directory,
    )

    assert selected == transit_candidate


