def test_stale_dynamic_route_hazard_does_not_block_a_different_policy(
    tmp_path,
) -> None:
    config_path, database = _write_campaign_files(tmp_path)
    spec = load_campaign_spec(config_path)
    policy = ProgressionPolicy(
        policy_id="solace-magnus-probe-19-20",
        minimum_level=19,
        maximum_level=20,
        status="research",
        execution="solace-magnus-research",
        summary="Probe a different current-band route.",
        evidence=(),
        practice_skill=None,
    )
    with RunStorage(database) as storage:
        campaign_id = storage.create_campaign(
            name=spec.name,
            config_path=config_path.resolve(),
            character_profile_path=spec.character_profile,
            target_level=spec.target_level,
        )
        storage.record_campaign_checkpoint(
            campaign_id,
            segment_id=None,
            run_id=None,
            phase="highland-keeper-probe-17-20",
            reason="ready",
            state={
                "level": 19,
                "xp": 180_000,
                "world_boot_id": "boot-1",
                "campaign_last_policy": "highland-keeper-probe-17-20",
                "campaign_fastwalk_abort_reason": (
                    "unexpected combat interrupted a no-combat field probe"
                ),
                "campaign_research_results": {
                    "highland-keeper-probe-17-20": {
                        "observed": False,
                        "viable": False,
                        "route_hazard": (
                            "unexpected combat interrupted a no-combat field probe"
                        ),
                        "boot_id": "boot-1",
                    }
                },
                "campaign_research_absence_cooldowns": {
                    "highland-keeper-probe-17-20": 3,
                },
                "campaign_policy_revision": _CAMPAIGN_POLICY_REVISION,
            },
        )

    async def different_route_segment(
        character,
        profile_path: Path,
    ) -> RunResult:
        return _record_segment_run(
            character.database,
            profile_path,
            {
                "level": 19,
                "xp": 180_100,
                "world_boot_id": "boot-1",
            },
        )

    class DifferentRouteRunner(CampaignRunner):
        def _policy_for_state(self, state) -> ProgressionPolicy:
            return policy

    result = asyncio.run(
        DifferentRouteRunner(
            spec,
            config_path,
            segment_runner=different_route_segment,
        ).run()
    )

    assert result.ready_for_next_segment is True
    with RunStorage(database) as storage:
        segments = storage.list_campaign_segments(campaign_id)
    assert [segment["phase"] for segment in segments] == [policy.policy_id]


def test_campaign_reconstructs_latest_flight_purchase_result(tmp_path) -> None:
    with RunStorage(tmp_path / "runs.sqlite3") as storage:
        campaign_id = storage.create_campaign(
            name="flight",
            config_path=tmp_path / "campaign.yaml",
            character_profile_path=tmp_path / "character.yaml",
            target_level=10,
        )
        first = storage.start_campaign_segment(
            campaign_id,
            phase="buy-flight-potion",
            start_state={"level": 9},
        )
        storage.finish_campaign_segment(
            first,
            status="success",
            run_id=None,
            end_state={"level": 9, "magic_shop_purchase_failed": True},
            command_count=1,
            duration_seconds=1.0,
        )
        field = storage.start_campaign_segment(
            campaign_id,
            phase="field-hunt",
            start_state={"level": 9},
        )
        storage.finish_campaign_segment(
            field,
            status="success",
            run_id=None,
            end_state={"level": 9, "magic_shop_purchase_failed": False},
            command_count=1,
            duration_seconds=1.0,
        )

        assert _campaign_flight_purchase_failed(storage, campaign_id) is True


def test_campaign_retries_flight_purchase_after_money_increases(tmp_path) -> None:
    with RunStorage(tmp_path / "runs.sqlite3") as storage:
        campaign_id = storage.create_campaign(
            name="flight",
            config_path=tmp_path / "campaign.yaml",
            character_profile_path=tmp_path / "character.yaml",
            target_level=10,
        )
        segment_id = storage.start_campaign_segment(
            campaign_id,
            phase="buy-flight-potion",
            start_state={"level": 9},
        )
        storage.finish_campaign_segment(
            segment_id,
            status="success",
            run_id=None,
            end_state={
                "level": 9,
                "currencies": {"silver": 10, "copper": 18},
                "magic_shop_purchase_failed": True,
                "world_boot_id": "boot-a",
            },
            command_count=1,
            duration_seconds=1.0,
        )

        assert (
            _campaign_flight_purchase_failed(
                storage,
                campaign_id,
                current_state={
                    "currencies": {"silver": 10, "copper": 18},
                    "world_boot_id": "boot-a",
                },
            )
            is True
        )
        assert (
            _campaign_flight_purchase_failed(
                storage,
                campaign_id,
                current_state={
                    "currencies": {"silver": 16, "copper": 19},
                    "world_boot_id": "boot-a",
                },
            )
            is False
        )


