def test_campaign_state_detects_active_flight_and_converts_coins(tmp_path) -> None:
    config_path, _ = _write_campaign_files(tmp_path)
    runner = CampaignRunner(load_campaign_spec(config_path), config_path)

    policy = runner._policy_for_state(
        {
            "level": 9,
            "inventory": [[
                {"short_desc": "a large sack"},
                {"short_desc": "a big pot pie"},
            ]],
            "affects": [[{"name": "fly", "duration": "12"}]],
            "currencies": {"silver": 17},
            "campaign_stalled_segments": 2,
        }
    )

    assert policy.policy_id == "ambush-exterior-9-10"

    stale_flight_after_route_abort = runner._policy_for_state(
        {
            "level": 19,
            "inventory": [[
                {"short_desc": "a large sack"},
                {"short_desc": "a big pot pie"},
            ]],
            "affects": [[{"name": "fly", "duration": "0"}]],
            "currencies": {"silver": 17},
            "campaign_fastwalk_abort_reason": (
                "field route requires active fly or levitation"
            ),
        }
    )

    assert stale_flight_after_route_abort.policy_id == "buy-flight-potion"

    less_than_an_hour_policy = runner._policy_for_state(
        {
            "level": 9,
            "inventory": [[
                {"short_desc": "a large sack"},
                {"short_desc": "a big pot pie"},
            ]],
            "affects": [[{"name": "fly", "duration": "0"}]],
            "currencies": {"silver": 17},
            "campaign_stalled_segments": 2,
        }
    )

    assert less_than_an_hour_policy.policy_id == "ambush-exterior-9-10"

    levitating_policy = runner._policy_for_state(
        {
            "level": 9,
            "inventory": [[
                {"short_desc": "a large sack"},
                {"short_desc": "a big pot pie"},
            ]],
            "affects": [[{"name": "levitation", "duration": "12"}]],
            "currencies": {"silver": 17},
            "campaign_stalled_segments": 2,
        }
    )

    assert levitating_policy.policy_id == "ambush-exterior-9-10"


def test_source_ranked_route_refreshes_duration_zero_flight_reserve() -> None:
    flight_candidate = replace(
        _source_test_candidate(
            target="a flight target",
            level_range=(18, 22),
        ),
        requires_flight=True,
        estimated_flying_move_cost=50,
    )

    assert _source_ranked_candidate_needs_flight_refresh(
        flight_candidate,
        {"affects": [[{"name": "fly", "duration": "0"}]]},
    )
    assert _source_ranked_candidate_needs_flight_refresh(
        flight_candidate,
        {"affects": [[{"name": "fly", "duration": "1"}]]},
    )
    assert not _source_ranked_candidate_needs_flight_refresh(
        flight_candidate,
        {"affects": [[{"name": "fly", "duration": "2"}]]},
    )
    long_route_candidate = replace(
        flight_candidate,
        route=("south",) * 121,
    )
    assert _source_ranked_candidate_needs_flight_refresh(
        long_route_candidate,
        {"affects": [[{"name": "fly", "duration": "2"}]]},
    )
    assert not _source_ranked_candidate_needs_flight_refresh(
        long_route_candidate,
        {"affects": [[{"name": "fly", "duration": "3"}]]},
    )
    assert not _source_ranked_candidate_needs_flight_refresh(
        flight_candidate,
        {"affects": None},
    )


def test_abyss_source_route_requires_fresh_flight_and_full_movement() -> None:
    abyss_candidate = replace(
        _source_test_candidate(
            target="a copepod",
            level_range=(18, 22),
        ),
        area_file="abyss.are",
        requires_flight=True,
        estimated_flying_move_cost=96,
    )
    state = {
        "affects": [[{"name": "fly", "duration": "15"}]],
        "max_move": 360,
    }

    assert _source_ranked_candidate_needs_flight_refresh(abyss_candidate, state)
    state["affects"] = [[{"name": "fly", "duration": "16"}]]
    assert not _source_ranked_candidate_needs_flight_refresh(abyss_candidate, state)
    assert _source_candidate_required_move(abyss_candidate, state) == 360


@pytest.mark.parametrize("boundary", [
    "available", "no-source", "weak", "purchase-failed", "combat-aborted",
])
def test_bounded_city_transit_replans_only_a_route_obstruction(tmp_path, monkeypatch, boundary):
    from dd4tester.city_travel import CITY_TRANSIT_KEY
    from dd4tester.hunt_candidates import load_world_source

    config_path, _ = _write_campaign_files(tmp_path)
    runner = CampaignRunner(load_campaign_spec(config_path), config_path)
    if boundary != "no-source":
        runner._source_world = load_world_source(
            Path("runs/dd4-source/server/area"), include_all_areas=True,
        )
    target = replace(
        _source_test_candidate(target="a distant ground target", level_range=(18, 22)),
        route=("south",) * 65, estimated_move_cost=335,
        estimated_flying_move_cost=99, requires_flight=False,
    )
    monkeypatch.setattr("dd4tester.campaign.policy_for", lambda *args, **kwargs: _SOURCE_RANKED_HUNT_POLICY)
    monkeypatch.setattr(runner, "_select_source_ranked_candidate", lambda *args, **kwargs: target)
    state = {
        "level": 21, "max_hp": 30 if boundary == "weak" else 113,
        "world_boot_id": "boot-1", "affects": [], "currencies": {"gold": 4},
        "inventory": [[{"short_desc": "a big pot pie"}]],
        "magic_shop_route_blocked_by_drunk": True,
        "magic_shop_purchase_failed": boundary == "purchase-failed",
        _FLIGHT_PURCHASE_COOLDOWN_KEY: 2, "campaign_city_shop_route_cooldown": 2,
        "campaign_xp_loss_total": 118,
    }
    if boundary == "combat-aborted":
        state[CITY_TRANSIT_KEY] = {"status": "aborted", "level": 21, "boot_id": "boot-1"}
    selected = runner._policy_for_state(state)
    assert selected.execution == ("buy-optional-flight" if boundary == "available" else "source-ranked-hunt")
    assert state["magic_shop_route_blocked_by_drunk"]
    assert state[_FLIGHT_PURCHASE_COOLDOWN_KEY] == 2
    assert state["campaign_xp_loss_total"] == 118


