def test_campaign_file_reports_attempt_progress(tmp_path, monkeypatch) -> None:
    config_path, database = _write_campaign_files(tmp_path)
    calls = 0
    progress: list[str] = []

    async def segment(spec, profile_path: Path) -> RunResult:
        nonlocal calls
        calls += 1
        return _record_segment_run(
            spec.database,
            profile_path,
            {"level": min(2, calls), "xp": calls * 100},
        )

    class TestRunner(CampaignRunner):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, segment_runner=segment, **kwargs)

    monkeypatch.setattr("dd4tester.campaign.CampaignRunner", TestRunner)

    result = asyncio.run(
        run_campaign_file(
            config_path,
            segments=2,
            progress_callback=progress.append,
        )
    )

    assert result.status == "ready"
    preparation = [line for line in progress if line.startswith("Campaign preparation:")]
    assert len(preparation) == 12
    assert "loading source and saved history" in preparation[0]
    assert "saved history loaded; repairing evidence" in preparation[1]
    assert "evidence repaired; selecting policy" in preparation[2]
    assert "policy selection complete" in preparation[3]
    assert "execution gates checked" in preparation[4]
    assert "segment plan prepared" in preparation[5]
    policy_preparation = [
        line for line in progress
        if line.startswith("Policy preparation:")
    ]
    assert len(policy_preparation) >= 2
    assert any("level 1" in line for line in policy_preparation)
    assert any("level 2" in line for line in policy_preparation)
    progress = [line for line in progress if not line.startswith("Campaign preparation:")]
    progress = [line for line in progress if not line.startswith("Policy preparation:")]
    assert len(progress) == 8
    assert progress[0] == (
        "Starting campaign attempt 1; source analysis and live execution are bounded."
    )
    assert progress[1].startswith("Policy selected: ")
    assert "execution=starter" in progress[1]
    assert progress[2].startswith("Opening segment: policy=")
    assert "execution=starter" in progress[2]
    assert progress[3] == (
        "Completed campaign attempt 1: status=ready; checkpoint=1; "
        "level=1; xp=100."
    )
    assert progress[4] == (
        "Starting campaign attempt 2; source analysis and live execution are bounded."
    )
    assert progress[5].startswith("Policy selected: ")
    assert "execution=starter" in progress[5]
    assert progress[6].startswith("Opening segment: policy=")
    assert "execution=starter" in progress[6]
    assert progress[7] == (
        "Completed campaign attempt 2: status=ready; checkpoint=2; "
        "level=2; xp=200."
    )


