    monkeypatch.setattr("dd4tester.campaign.asyncio.sleep", fake_sleep)

    result = asyncio.run(
        run_campaign_file(
            config_path,
            segments=2,
            reset_wait=42,
        )
    )

    assert result.status == "success"
    assert calls == [(True, False, False), (True, True, True)]
    assert waits == [42]


