def test_campaign_selects_subclass_change_only_from_live_level_thirty_state(
    tmp_path: Path,
) -> None:
    config_path, _database = _write_campaign_files(tmp_path)
    profile_path = tmp_path / "character.yaml"
    profile_path.write_text(
        profile_path.read_text(encoding="utf-8").replace(
            "class: mage",
            "class: thief",
        )
        + "\nsubclass: ninja\n",
        encoding="utf-8",
    )
    runner = CampaignRunner(load_campaign_spec(config_path), config_path)
    state = {
        "level": 30,
        "subclass": "none",
        "room_vnum": "3054",
        "hp": 300,
        "max_hp": 300,
        "mana": 250,
        "max_mana": 250,
        "move": 300,
        "max_move": 300,
        "room_flags": ["safe", "healing"],
        "affects": [],
    }

    selected = runner._policy_for_state(state)

    assert selected.policy_id == "choose-subclass-30"
    assert selected.execution == "choose-subclass"

    state["subclass"] = "ninja"
    released = runner._policy_for_state(state)

    assert released.policy_id != "choose-subclass-30"


@pytest.mark.parametrize(
    ("character_class", "subclass"),
    (
        ("mage", "necromancer"),
        ("mage", "warlock"),
        ("cleric", "templar"),
        ("cleric", "druid"),
        ("thief", "ninja"),
        ("thief", "bounty hunter"),
        ("warrior", "knight"),
        ("warrior", "thug"),
        ("psionic", "infernalist"),
        ("psionic", "witch"),
        ("shifter", "werewolf"),
        ("shifter", "vampire"),
        ("brawler", "monk"),
        ("brawler", "martial artist"),
        ("ranger", "barbarian"),
        ("ranger", "bard"),
        ("smithy", "engineer"),
        ("smithy", "runesmith"),
    ),
)
def test_campaign_preflights_the_exact_subclass_teacher(
    tmp_path: Path,
    character_class: str,
    subclass: str,
) -> None:
    config_path, _database = _write_campaign_files(tmp_path)
    profile_path = tmp_path / "character.yaml"
    profile = profile_path.read_text(encoding="utf-8")
    if character_class != "mage":
        profile = profile.replace("class: mage", f"class: {character_class}")
    profile_path.write_text(
        profile + f"\nsubclass: {subclass}\n",
        encoding="utf-8",
    )
    runner = CampaignRunner(load_campaign_spec(config_path), config_path)
    runner._source_world = load_world_source(
        Path("runs/dd4-source/server/area"),
        include_all_areas=True,
    )
    selected = ProgressionPolicy(
        policy_id="choose-subclass-30",
        minimum_level=30,
        maximum_level=None,
        status="research",
        execution="choose-subclass",
        summary="Select the requested subclass.",
        evidence=(),
        practice_skill=None,
    )

    checked = runner._subclass_source_preflight_policy(
        {"level": 30},
        selected,
    )

    assert checked.policy_id == selected.policy_id
    assert checked.execution == selected.execution
    assert any(
        "Source-verified subclass teacher: mobile VNUM" in evidence
        and f"teaches {source_subclass_teacher_skill(subclass)!r}" in evidence
        for evidence in checked.evidence
    )


def test_policy_revision_reopens_closed_exit_listing_abort_once() -> None:
    policy_id = "source-ranked-hunt-ambush-4519-4525-18"
    abort_reason = (
        "field room listing remained unavailable after one bounded retry"
    )
    migrated = _refresh_policy_revision(
        {
            "level": 18,
            "campaign_policy_revision": 250,
            "campaign_last_policy": policy_id,
            "campaign_fastwalk_abort_reason": abort_reason,
            "campaign_fastwalk_target_absent": False,
            "campaign_fastwalk_target_present_observed": False,
            "campaign_fastwalk_crowded": False,
            "campaign_fastwalk_consider_outcomes": {},
            "campaign_research_results": {
                policy_id: {
                    "boot_id": "boot-1",
                    "observed": False,
                    "route_hazard": abort_reason,
                    "viable": False,
                },
                "other-policy": {
                    "boot_id": "boot-1",
                    "observed": True,
                    "viable": True,
                },
            },
            _RESEARCH_ABSENCE_COOLDOWN_KEY: {
                policy_id: 3,
                "other-policy": 2,
            },
            _CLEARED_RESEARCH_POLICIES_KEY: [policy_id, "other-policy"],
            "world_boot_id": "boot-1",
            "room_vnum": "3054",
            "room_flags": ["safe", "healing"],
            "enemies": None,
            "dead": False,
            "in_combat": False,
            "campaign_died_during_segment": False,
            "xp_loss_observed": False,
            "campaign_xp_loss_observed": False,
        }
    )

    assert migrated["campaign_policy_revision"] == _CAMPAIGN_POLICY_REVISION
    assert policy_id not in migrated["campaign_research_results"]
    assert migrated["campaign_research_results"]["other-policy"]["viable"] is True
    assert migrated[_RESEARCH_ABSENCE_COOLDOWN_KEY] == {"other-policy": 2}
    assert migrated[_CLEARED_RESEARCH_POLICIES_KEY] == ["other-policy"]
    assert migrated[_SOURCE_RANKED_REVALIDATION_POLICY_KEY] == policy_id
    assert "campaign_last_policy" not in migrated
    assert "campaign_fastwalk_abort_reason" not in migrated


